// ---- LOGIN ----
function renderLogin(){
  document.getElementById('app').innerHTML = `
    <div class="login-screen">
      <img src="data:image/png;base64," style="width:120px;height:120px;border-radius:50%;margin-bottom:8px;object-fit:cover">
      <div class="login-title">HARMONIA</div>
      <div class="login-sub">Fundado em 01/03/97</div>
      <div style="width:100%;max-width:320px">
        <div class="card">
          <div class="card-title">Entrar</div>
          <div class="form-group">
            <label>Número de celular (somente números)</label>
            <input type="tel" id="login-phone" placeholder="Ex: 48999999999" maxlength="15" inputmode="numeric"
              onkeydown="if(event.key==='Enter') doLogin()">
          </div>
          <button class="btn btn-primary" onclick="doLogin()">Entrar</button>
          <button class="btn btn-secondary" id="passkey-btn" onclick="tryPasskeyLogin()" style="display:none">👆 Entrar com biometria</button>
          <button class="btn btn-secondary" onclick="renderRegister()">Primeiro acesso — Cadastrar</button>
        </div>
      </div>
    </div>
  `;
  // Show passkey button if passkeys are registered
  setTimeout(async()=>{
    if(window.PublicKeyCredential){
      const store = JSON.parse(localStorage.getItem('harmonia_passkeys')||'{}');
      const btn = document.getElementById('passkey-btn');
      if(btn && Object.keys(store).length) btn.style.display='';
    }
  },50);
}

function renderRegister(){
  document.getElementById('app').innerHTML = `
    <div class="login-screen" style="justify-content:flex-start;padding-top:24px">
      <img src="data:image/png;base64," style="width:64px;height:64px;border-radius:50%;object-fit:cover">
      <div class="login-title" style="font-size:20px;margin-bottom:4px">Novo cadastro</div>
      <div style="width:100%;max-width:320px;margin-top:16px">
        <div class="card">
          <div class="form-group"><label>Nome completo</label><input id="r-name" placeholder="Seu nome completo"></div>
          <div class="form-group"><label>Celular (somente números)</label><input type="tel" id="r-phone" placeholder="48999999999" maxlength="15" inputmode="numeric"></div>
          <div class="row-2">
            <div class="form-group"><label>Data de nascimento</label><input type="date" id="r-birth"></div>
            <div class="form-group"><label>Posição</label>
              <select id="r-pos">${POSITIONS.map(p=>`<option>${p}</option>`).join('')}</select>
            </div>
          </div>
          <button class="btn btn-primary" onclick="doRegister()">Cadastrar</button>
          <button class="btn btn-secondary" onclick="renderLogin()">Voltar</button>
        </div>
      </div>
    </div>
  `;
}

async function hashPassword(pwd){
  const enc = new TextEncoder().encode(pwd);
  const buf = await crypto.subtle.digest('SHA-256', enc);
  return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,'0')).join('');
}

async function doLogin(){
  const phone = document.getElementById('login-phone')?.value?.replace(/\D/g,'');
  if(!phone||phone.length<8){ toast('Informe um número válido','err'); return; }
  const player = appData.players.find(p=>p.phone===phone);
  if(!player){ toast('Número não cadastrado. Faça seu cadastro.','err'); return; }

  // Admin — se não tiver senha ainda, vai direto criar senha; senão pede senha normalmente
  if(isAdminPhone(phone)){
    if(!player.password_hash){
      renderSetPassword(phone);
    } else {
      renderPasswordLogin(phone, player);
    }
    return;
  }

  // Not yet activated — show activation screen
  if(!player.password_hash){
    if(!player.activation_code){
      // Show a nicer screen instead of just a toast
      renderNeedActivation(phone, player);
      return;
    }
    renderActivation(phone, player);
    return;
  }

  // Has password — show password screen
  renderPasswordLogin(phone, player);
}

function renderNeedActivation(phone, player){
  document.getElementById('app').innerHTML = `
    <div class="login-screen">
      <div class="login-logo" style="font-size:40px">🔑</div>
      <div class="login-title" style="font-size:18px">Ativação necessária</div>
      <div class="login-sub">Sua conta ainda não tem senha</div>
      <div style="width:100%;max-width:320px">
        <div class="card">
          <div style="font-size:13px;color:var(--gray4);line-height:1.6;margin-bottom:16px">
            Para proteger sua conta, é necessário criar uma senha.<br><br>
            Peça ao administrador para gerar seu <strong>código de ativação</strong> no painel de Jogadores e enviar pelo WhatsApp.
          </div>
          <div style="background:var(--gray);border-radius:8px;padding:10px 14px;font-size:12px;color:var(--gray4);margin-bottom:14px">
            📱 Seu número: <strong>${phone}</strong>
          </div>
          <button class="btn btn-primary" onclick="renderActivation('${phone}', appData.players.find(p=>p.phone==='${phone}'))">
            Já tenho o código
          </button>
          <button class="btn btn-secondary" onclick="renderLogin()">Voltar</button>
        </div>
      </div>
    </div>
  `;
}

function isAdminPhone(phone){ return !!appData.players.find(p=>p.phone===phone && playerIsAdmin(p)); }

function finishLogin(player, fromPassword=false){
  currentPhone = player.phone;
  currentPlayer = player;
  sessionStorage.setItem('pelada_phone', player.phone);
  currentTab = 'home';
  render();
  if(appData.game?.open){
    setTimeout(()=>toast('🔔 Jogo aberto para confirmações!'),500);
  }
  if(fromPassword) offerPasskey(player.phone);
}

function renderPasswordLogin(phone, player){
  document.getElementById('app').innerHTML = `
    <div class="login-screen">
      <div class="login-logo" style="font-size:40px">🔒</div>
      <div class="login-title" style="font-size:20px">Olá, ${player.name.split(' ')[0]}!</div>
      <div class="login-sub">Digite sua senha para entrar</div>
      <div style="width:100%;max-width:320px">
        <div class="card">
          <div class="form-group">
            <label>Senha</label>
            <input type="password" id="pw-input" placeholder="Sua senha" autocomplete="current-password"
              onkeydown="if(event.key==='Enter') submitPassword('${phone}')">
          </div>
          <button class="btn btn-primary" onclick="submitPassword('${phone}')">Entrar</button>
          <button class="btn btn-secondary" onclick="renderForgotPassword('${phone}')">Esqueci minha senha</button>
          <button class="btn btn-secondary" onclick="renderLogin()">Voltar</button>
        </div>
      </div>
    </div>
  `;
  setTimeout(()=>document.getElementById('pw-input')?.focus(),100);
}

async function submitPassword(phone){
  const pwd = document.getElementById('pw-input')?.value;
  if(!pwd){ toast('Digite sua senha','err'); return; }
  const player = appData.players.find(p=>p.phone===phone);
  if(!player) return;
  const hash = await hashPassword(pwd);
  if(hash !== player.password_hash){
    toast('Senha incorreta','err');
    document.getElementById('pw-input').value='';
    document.getElementById('pw-input').focus();
    return;
  }
  finishLogin(player, true);
}

function renderActivation(phone, player){
  document.getElementById('app').innerHTML = `
    <div class="login-screen">
      <div class="login-logo" style="font-size:40px">🔑</div>
      <div class="login-title" style="font-size:20px">Ativar conta</div>
      <div class="login-sub">Digite o código enviado pelo admin no WhatsApp</div>
      <div style="width:100%;max-width:320px">
        <div class="card">
          <div class="form-group">
            <label>Código de ativação (6 dígitos)</label>
            <input type="number" id="act-code" placeholder="000000" maxlength="6" inputmode="numeric"
              style="letter-spacing:4px;font-size:20px;text-align:center">
          </div>
          <button class="btn btn-primary" onclick="submitActivation('${phone}')">Confirmar código</button>
          <button class="btn btn-secondary" onclick="renderLogin()">Voltar</button>
        </div>
      </div>
    </div>
  `;
}

async function submitActivation(phone){
  const code = document.getElementById('act-code')?.value?.trim();
  if(!code||code.length<6){ toast('Digite o código de 6 dígitos','err'); return; }
  const player = appData.players.find(p=>p.phone===phone);
  if(!player) return;
  if(String(player.activation_code) !== String(code)){
    toast('Código incorreto','err'); return;
  }
  // Code correct — show set password screen
  renderSetPassword(phone);
}

function renderSetPassword(phone){
  document.getElementById('app').innerHTML = `
    <div class="login-screen">
      <div class="login-logo" style="font-size:40px">🔐</div>
      <div class="login-title" style="font-size:20px">Criar senha</div>
      <div class="login-sub">Escolha uma senha para acessos futuros</div>
      <div style="width:100%;max-width:320px">
        <div class="card">
          <div class="form-group">
            <label>Nova senha (mín. 4 caracteres)</label>
            <input type="password" id="new-pw" placeholder="Digite sua senha" autocomplete="new-password">
          </div>
          <div class="form-group">
            <label>Confirmar senha</label>
            <input type="password" id="new-pw2" placeholder="Repita a senha"
              onkeydown="if(event.key==='Enter') saveNewPassword('${phone}', false)">
          </div>
          <button class="btn btn-primary" onclick="saveNewPassword('${phone}', false)">Salvar senha e entrar</button>
        </div>
      </div>
    </div>
  `;
}

async function saveNewPassword(phone, isReset){
  const pwd = document.getElementById('new-pw')?.value;
  const pwd2 = document.getElementById('new-pw2')?.value;
  if(!pwd||pwd.length<4){ toast('Senha deve ter ao menos 4 caracteres','err'); return; }
  if(pwd !== pwd2){ toast('As senhas não coincidem','err'); return; }
  const hash = await hashPassword(pwd);
  const btn = document.querySelector('.btn-primary');
  if(btn) btn.disabled=true;
  const {data, error} = await sb.from('players')
    .update({password_hash: hash, activation_code: null})
    .eq('phone', phone).select().single();
  if(error){ toast('Erro: '+error.message,'err'); if(btn) btn.disabled=false; return; }
  const idx = appData.players.findIndex(p=>p.phone===phone);
  if(idx>=0) appData.players[idx] = data;
  toast('Senha criada com sucesso!');
  finishLogin(data, true);
}

function renderForgotPassword(phone){
  const player = appData.players.find(p=>p.phone===phone);
  document.getElementById('app').innerHTML = `
    <div class="login-screen">
      <div class="login-logo" style="font-size:40px">🔓</div>
      <div class="login-title" style="font-size:20px">Recuperar senha</div>
      <div class="login-sub">Confirme sua data de nascimento</div>
      <div style="width:100%;max-width:320px">
        <div class="card">
          <div class="form-group">
            <label>Data de nascimento</label>
            <input type="date" id="rec-birth"
              onkeydown="if(event.key==='Enter') submitRecovery('${phone}')">
          </div>
          <button class="btn btn-primary" onclick="submitRecovery('${phone}')">Confirmar</button>
          <button class="btn btn-secondary" onclick="renderLogin()">Voltar</button>
        </div>
      </div>
    </div>
  `;
}

async function submitRecovery(phone){
  const birth = document.getElementById('rec-birth')?.value;
  if(!birth){ toast('Informe sua data de nascimento','err'); return; }
  const player = appData.players.find(p=>p.phone===phone);
  if(!player||player.birth_date !== birth){
    toast('Data de nascimento incorreta','err'); return;
  }
  renderSetPassword(phone);
}

async function doRegister(){
  const name = document.getElementById('r-name')?.value?.trim();
  const phone = document.getElementById('r-phone')?.value?.replace(/\D/g,'');
  const birth = document.getElementById('r-birth')?.value;
  const position = document.getElementById('r-pos')?.value;
  if(!name||!phone||!birth){ toast('Preencha todos os campos','err'); return; }
  if(phone.length<8){ toast('Número de celular inválido','err'); return; }
  if(appData.players.find(p=>p.phone===phone)){ toast('Número já cadastrado','err'); return; }
  const btn = document.querySelector('.btn-primary');
  if(btn) btn.disabled=true;
  const {data,error} = await sb.from('players').insert({name,phone,birth_date:birth,position,mens_ok:false}).select().single();
  if(error){ toast('Erro: '+error.message,'err'); if(btn) btn.disabled=false; return; }
  appData.players.push(data);
  toast('Cadastro realizado! Faça login.');
  renderLogin();
}

function logout(){
  currentPhone=null; currentPlayer=null;
  sessionStorage.removeItem('pelada_phone');
  currentTab='home'; render();
}

